def choose_move(observation):
    def get_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for ks in (("pos",), ("position",), ("loc",), ("location",), ("xy",)):
                for k in ks:
                    v = obj.get(k)
                    if isinstance(v, (list, tuple)) and len(v) >= 2:
                        return [v[0], v[1]]
            x = obj.get("x")
            y = obj.get("y")
            if x is not None and y is not None:
                return [x, y]
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return [obj[0], obj[1]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def best_toward(src, targets):
        if not src or not targets:
            return None
        best = None
        bd = None
        for t in targets:
            if t is None:
                continue
            d = manhattan(src, t)
            if bd is None or d < bd:
                bd = d
                best = t
        if best is None:
            return None
        dx = best[0] - src[0]
        dy = best[1] - src[1]
        return [clamp_step(dx), clamp_step(dy)]

    def best_away(src, threats):
        if not src or not threats:
            return None
        worst = None
        wd = None
        for t in threats:
            if t is None:
                continue
            d = manhattan(src, t)
            if wd is None or d < wd:
                wd = d
                worst = t
        if worst is None:
            return None
        dx = src[0] - worst[0]
        dy = src[1] - worst[1]
        return [clamp_step(dx), clamp_step(dy)]

    def extract_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            for k in ("items", "agents", "players", "enemies", "resources", "targets", "goals", "cells", "territories", "territory"):
                if k in value:
                    out.extend(extract_positions(value.get(k)))
            if not out:
                p = get_pos(value)
                if p is not None:
                    out.append(p)
            return out
        if isinstance(value, (list, tuple)):
            for it in value:
                if isinstance(it, (list, tuple)) and len(it) >= 2 and not isinstance(it[0], (list, tuple, dict)):
                    out.append([it[0], it[1]])
                else:
                    p = get_pos(it)
                    if p is not None:
                        out.append(p)
            return out
        p = get_pos(value)
        if p is not None:
            out.append(p)
        return out

    obs = observation if isinstance(observation, dict) else {}

    self_pos = None
    for key in ("self", "agent", "me", "player", "unit", "avatar"):
        self_pos = get_pos(obs.get(key))
        if self_pos is not None:
            break
    if self_pos is None:
        self_pos = get_pos(obs.get("pos")) or get_pos(obs.get("position"))
    if self_pos is None:
        self_pos = [0, 0]

    resources = []
    for key in ("resources", "resource", "food", "gold", "items", "collectibles", "pickups"):
        resources.extend(extract_positions(obs.get(key)))

    enemies = []
    for key in ("enemies", "enemy", "opponents", "opponent", "players", "adversaries"):
        enemies.extend(extract_positions(obs.get(key)))

    allies = []
    for key in ("allies", "teammates", "friends"):
        allies.extend(extract_positions(obs.get(key)))

    goals = []
    for key in ("goals", "goal", "targets", "target", "objective", "objectives", "bases", "base"):
        goals.extend(extract_positions(obs.get(key)))

    territory = []
    for key in ("territory", "frontier", "unclaimed", "claimed"):
        territory.extend(extract_positions(obs.get(key)))

    # Infer mode from available signals
    mode = obs.get("mode") or obs.get("game") or obs.get("type") or ""

    move = [0, 0]

    # Pursuit/evasion: avoid nearest enemy if too close, else chase if strong signals suggest pursuit.
    enemy_move = best_away(self_pos, enemies)
    if enemy_move is not None and (mode == "pursuit_evasion" or (enemies and manhattan(self_pos, min(enemies, key=lambda p: manhattan(self_pos, p))) <= 3)):
        move = enemy_move

    # Resource collection: go to nearest resource.
    if resources:
        toward = best_toward(self_pos, resources)
        if toward is not None and (mode == "resource_collection" or not enemies):
            move = toward

    # Territory control: move toward frontier/goals; slightly avoid enemies.
    if territory or goals:
        target_list = goals if goals else territory
        toward = best_toward(self_pos, target_list)
        if toward is not None and (mode == "territory_control" or not resources):
            move = toward

    # Mixed fallback: prefer closest interesting entity.
    if move == [0, 0]:
        candidates = []
        for lst, w in ((resources, 3), (goals, 2), (territory, 2), (enemies, 1)):
            for p in lst:
                candidates.append((p, w))
        if candidates:
            best = None
            best_score = None
            for p, w in candidates:
                d = manhattan(self_pos, p)
                score = d - w
                if best_score is None or score < best_score:
                    best_score = score
                    best = p
            if best is not None:
                move = [clamp_step(best[0] - self_pos[0]), clamp_step(best[1] - self_pos[1])]

    # If enemy is adjacent, prioritize escape even if pursuing/collecting.
    close_threat = None
    close_dist = None
    for e in enemies:
        d = manhattan(self_pos, e)
        if close_dist is None or d < close_dist:
            close_dist = d
            close_threat = e
    if close_threat is not None and close_dist is not None and close_dist <= 1:
        move = [clamp_step(self_pos[0] - close_threat[0]), clamp_step(self_pos[1] - close_threat[1])]

    if move[0] == 0 and move[1] == 0:
        # Deterministic exploratory nudge.
        if resources:
            move = [1, 0]
        elif goals or territory:
            move = [0, 1]
        elif enemies:
            move = [clamp_step(self_pos[0] - enemies[0][0]), clamp_step(self_pos[1] - enemies[0][1])]
        else:
            move = [1, 0]

    move[0] = clamp_step(move[0])
    move[1] = clamp_step(move[1])
    return [move[0], move[1]]

